package be.imgn.inject.maven;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugins.annotations.LifecyclePhase;
import org.apache.maven.plugins.annotations.Mojo;
import org.apache.maven.plugins.annotations.Parameter;
import org.jspecify.annotations.Nullable;

/**
 * Registers the factories generated by the annotation processor as {@code module-info} services, so a modular consumer
 * resolves them without hand-writing {@code provides} clauses.
 *
 * <p>When the project already compiles a {@code module-info.class}, its descriptor is patched to provide the generated
 * factories. When it has none, a descriptor is generated. Either way only the compiled output is written: the project's
 * sources are never modified, so the file the developer reads stays the file they wrote.
 *
 * <p>The goal is idempotent — an existing {@code provides} clause for the factory service is replaced, not appended to.
 * On the classpath (no modules involved) it is harmless: {@code ServiceLoader} still reads the
 * {@code META-INF/services} file the processor writes.
 */
@Mojo(name = "register-factories", defaultPhase = LifecyclePhase.PROCESS_CLASSES, threadSafe = true)
public class RegisterFactoriesMojo extends AbstractMojo {

    /** The compiled output directory to scan and patch. */
    @Parameter(defaultValue = "${project.build.outputDirectory}", required = true)
    private @Nullable File classesDirectory;

    /**
     * The module name to declare when the project has no {@code module-info.class}. Defaults to the project's group and
     * artifact identifiers; required only when a descriptor must be generated.
     */
    @Parameter(defaultValue = "${project.groupId}.${project.artifactId}")
    private @Nullable String moduleName;

    /** Whether to generate a {@code module-info.class} when the project has none. */
    @Parameter(defaultValue = "false", property = "inject.generateModuleInfo")
    private boolean generateModuleInfo;

    /** Whether to skip this goal entirely. */
    @Parameter(defaultValue = "false", property = "inject.skip")
    private boolean skip;

    @Override
    public void execute() throws MojoExecutionException {
        if (skip) {
            getLog().debug("inject: skipped");
            return;
        }
        Path classes = requireClassesDirectory();
        if (!Files.isDirectory(classes)) {
            getLog().debug("inject: no compiled output, nothing to register");
            return;
        }
        try {
            Map<String, List<String>> providers = InjectServices.read(classes);
            if (providers.isEmpty()) {
                getLog().debug("inject: no framework services registered, nothing to do");
                return;
            }
            register(classes, providers);
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to register framework services: " + e.getMessage(), e);
        }
    }

    private void register(Path classes, Map<String, List<String>> providers)
            throws IOException, MojoExecutionException {
        int count = providers.values().stream().mapToInt(List::size).sum();
        Path moduleInfo = classes.resolve("module-info.class");
        if (Files.isRegularFile(moduleInfo)) {
            if (ModuleInfoPatcher.addProvides(moduleInfo, providers)) {
                getLog().info("inject: registered " + count + " providers in module-info");
            }
            return;
        }
        if (!generateModuleInfo) {
            getLog().debug("inject: no module-info; providers remain discoverable via META-INF/services");
            return;
        }
        String name = moduleName;
        if (name == null || name.isBlank()) {
            throw new MojoExecutionException("moduleName is required to generate a module-info for " + classes + ".");
        }
        ModuleInfoGenerator.generate(classes, name, providers);
        getLog().info("inject: generated module-info for " + name + " providing " + count + " providers");
    }

    private Path requireClassesDirectory() throws MojoExecutionException {
        File directory = classesDirectory;
        if (directory == null) {
            throw new MojoExecutionException("classesDirectory is required.");
        }
        return directory.toPath();
    }
}
